-- 0011 breeder benchmark foundation (breeder-flock-performance ticket 03)
--
-- Official breed-company performance objectives, versioned and read-only
-- from every client. See
-- docs/superpowers/specs/2026-08-27-breeder-flock-performance-design.md
-- section 4 and local migration v69
-- (lib/data/database/database_migrations.dart, _applyV69Upgrade).
--
-- The seed rows below are generated from the SAME checked-in asset files
-- that lib/data/database/seeds/breeder_benchmark_seeds.dart imports locally
-- (assets/benchmarks/metric_definitions.json and
-- assets/benchmarks/aviagen_ross308_parent_stock_2021_en.json), so cloud and
-- local hold identical values. Do not hand-edit the values below; regenerate
-- them from the asset files if they ever change.
--
-- This file is deliberately NOT applied by this change — see
-- supabase/migrations_unapplied/README.md.

create table public.breeder_metric_definitions (
  id                 text primary key,
  code               text not null unique,
  label              text not null,
  unit               text not null,
  sex_scope          text not null check (sex_scope in ('female','male','both')),
  period_type        text not null check (period_type in ('daily','weekly','cumulative')),
  aggregation_method text not null check (aggregation_method in ('average','sum','cumulative')),
  display_precision  integer not null default 0,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
alter table public.breeder_metric_definitions enable row level security;
create policy breeder_metric_definitions_read on public.breeder_metric_definitions
  for select to authenticated using (true);

create table public.breeder_benchmark_profiles (
  id                        text primary key,
  profile_key               text not null unique,
  company                   text not null,
  breed                     text not null,
  product                   text not null,
  guide_version             text not null,
  publication_date          date,
  source_url                text not null,
  effective_age_start_days  integer not null default 0,
  effective_age_end_days    integer,
  lifecycle_coverage        text not null,
  state                     text not null default 'draft' check (state in ('draft','active','archived')),
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now()
);
alter table public.breeder_benchmark_profiles enable row level security;
create policy breeder_benchmark_profiles_read on public.breeder_benchmark_profiles
  for select to authenticated using (true);

-- Published (non-draft) profiles are immutable, enforced the same way as
-- the local SQLite triggers: no update/delete once state left 'draft'. No
-- write policy exists for any client role at all — the only writer is this
-- migration (as service_role, which bypasses RLS).
create or replace function public.breeder_benchmark_profile_immutable()
  returns trigger
  language plpgsql
  set search_path = ''
as $$
begin
  if old.state <> 'draft' then
    raise exception 'Published benchmark profile is immutable';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;
create trigger trg_breeder_benchmark_profiles_immutable
  before update or delete on public.breeder_benchmark_profiles
  for each row execute function public.breeder_benchmark_profile_immutable();

create table public.breeder_benchmark_values (
  id                text primary key,
  profile_id        text not null references public.breeder_benchmark_profiles(id) on delete cascade,
  metric_id         text not null references public.breeder_metric_definitions(id),
  sex               text not null check (sex in ('female','male','both')),
  age_days          integer not null,
  age_week          integer not null,
  production_week   integer,
  period_type       text not null check (period_type in ('daily','weekly','cumulative')),
  target_value      double precision,
  lower_bound       double precision,
  upper_bound       double precision,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (profile_id, metric_id, sex, age_days)
);
alter table public.breeder_benchmark_values enable row level security;
create policy breeder_benchmark_values_read on public.breeder_benchmark_values
  for select to authenticated using (true);

create or replace function public.breeder_benchmark_value_immutable()
  returns trigger
  language plpgsql
  set search_path = ''
as $$
declare
  profile_state text;
begin
  select state into profile_state from public.breeder_benchmark_profiles
    where id = coalesce(new.profile_id, old.profile_id);
  if profile_state is distinct from 'draft' then
    raise exception 'Benchmark values of a published profile are immutable';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;
create trigger trg_breeder_benchmark_values_immutable
  before insert or update or delete on public.breeder_benchmark_values
  for each row execute function public.breeder_benchmark_value_immutable();

-- Provenance note: 'hen_week_production_pct' is transcribed verbatim from
-- the Weekly Egg Production table's "Hen-Week (%)*" column (footnoted as
-- based on an assumed 8%/0.2%-per-week mortality curve), NOT from a
-- "Hen-Day" column -- the source document has no column literally headed
-- "Hen-Day" in that table. A genuine "Hen-Day (%)" heading does appear
-- elsewhere in the PDF, on the unrelated Feeding into Lay table (a
-- feed-by-production-milestone program), which this profile does not
-- import. Full per-metric source-column provenance for all 18 metrics is
-- recorded in assets/benchmarks/aviagen_ross308_parent_stock_2021_en.json
-- under "metricProvenance" -- read it there before relying on any value
-- below for a denominator-sensitive comparison (see design doc section 7.3).

